  'Roast v1: 8 home sections, Our story, Contact, FAQ pages'
FROM templates t
WHERE t.key = 'roast'
ON CONFLICT (template_id, version) DO NOTHING;

UPDATE templates t SET current_version_id = v.id, updated_at = now()
FROM template_versions v
WHERE t.key = 'roast' AND v.template_id = t.id AND v.version = 1
  AND t.current_version_id IS DISTINCT FROM v.id;

-- Rollback: DELETE FROM templates WHERE key = 'roast'; (cascades to its versions and installs).
